// _site-url.mjs - The project's public address, written ONCE in a generated file
// (src/lib/site-url.ts) that the metadata, the sitemap, robots.txt and the JSON-LD read (3.4.12).
// Until then each generated file fell back on "http://localhost:3000" when NEXT_PUBLIC_APP_URL
// was missing in production: share previews, canonical addresses and the sitemap then pointed at
// localhost. Used by setup-seo.mjs and setup-i18n.mjs.

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

export const SITE_URL_FILE = "src/lib/site-url.ts";
export const SITE_URL_IMPORT = 'import { siteUrl } from "~/lib/site-url";';

export const SITE_URL_SOURCE = `// The site's public address, read by the metadata, the sitemap, robots.txt and the JSON-LD
// (generated by Hypervibe).
//   1. NEXT_PUBLIC_APP_URL, the project's own (set by /bootstrap, then by /add-domain), unless it
//      names this machine in production;
//   2. on Vercel, the production domain Vercel publishes (VERCEL_PROJECT_PRODUCTION_URL, which
//      comes without its https://);
//   3. localhost, only when nothing else is known: local development.
function isLocal(url: string): boolean {
  try {
    const host = new URL(url).hostname;
    return host === "localhost" || host === "127.0.0.1";
  } catch {
    return false;
  }
}

function withoutTrailingSlash(url: string): string {
  return url.endsWith("/") ? url.slice(0, -1) : url;
}

export function siteUrl(): string {
  const own = process.env.NEXT_PUBLIC_APP_URL?.trim();
  if (own && !(process.env.VERCEL_ENV === "production" && isLocal(own))) return withoutTrailingSlash(own);
  const vercel = process.env.VERCEL_PROJECT_PRODUCTION_URL?.trim();
  if (vercel) return withoutTrailingSlash(\`https://\${vercel}\`);
  return "http://localhost:3000";
}
`;

/** Writes src/lib/site-url.ts under `webDir` when it is not there: "created" or "present". */
export function ensureSiteUrl(webDir = ".") {
  const file = join(webDir, SITE_URL_FILE);
  if (existsSync(file)) return "present";
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, SITE_URL_SOURCE);
  return "created";
}

/** Adds the helper's import right after the last import of a TypeScript source, once. */
export function withSiteUrlImport(source) {
  if (source.includes(SITE_URL_IMPORT)) return source;
  let end = -1;
  for (const m of source.matchAll(/^import\b[^;]*;/gm)) end = m.index + m[0].length;
  if (end < 0) return `${SITE_URL_IMPORT}\n${source}`;
  return `${source.slice(0, end)}\n${SITE_URL_IMPORT}${source.slice(end)}`;
}
